  p.add(meta("og:locality") || meta("business:contact_data:locality"));
  p.add(meta("og:region") || meta("business:contact_data:region") || meta("geo.region"));
  p.add(meta("og:postal-code") || meta("business:contact_data:postal_code"));
  p.add(meta("og:country-name") || meta("business:contact_data:country_name"));
  return p.join();
}

// Last-resort location: many event/listing pages title themselves
// "Event @ Venue" (bandsintown, secrettelaviv, Songkick, …). When nothing more
// structured exposed a location, take the part after the first " @ " in the
// page title as a best-effort venue. Bounded in length so a stray "@" in a
// long title doesn't turn a whole sentence into a location.
function venueFromTitle(title) {
  const i = (title || "").indexOf(" @ ");
  if (i < 0) return "";
  const venue = clean(title.slice(i + 3));
  return venue.length <= 80 ? venue : "";
}

// Href of a maps service — a "directions to us" link marks its own text as
// the site's street address.
const MAPS_SERVICE = /(?:maps\.google\.|google\.[a-z.]+\/maps|waze\.com|openstreetmap\.org|maps\.apple\.com|bing\.com\/maps)/i;
// An icon file whose name says "this is where we are" (location.png,
// map-pin.svg, map_marker.webp, …) — the wrapping link's text is the address.
const PIN_ICON = /(?:location|map[-_]?pin|map[-_]?marker)[^/]*\.(?:png|svg|gif|jpe?g|webp|ico)/i;

// Last-resort location: the street address a single-venue site (a club, a
// cinema, a theater) publishes once in its page chrome instead of repeating
// it in every event's details. The footer is scanned first, then the header
// (some venues use a top contact bar). Only deliberate "this is our address"
// markers are read — never arbitrary chrome text — in signal-strength order:
//   1. a maps-service link (Google Maps, Waze, OSM, Apple/Bing Maps)
//   2. an element whose class/id mentions "addres" (covers "address" and the
//      bare "addres" misspelling seen in the wild)
//   3. a link marked by a location-pin icon (PIN_ICON above)
// Each candidate must still read like a street address (looksLikeAddress), so
// "Get Directions" links, phone numbers, and copyright lines never qualify.
// Ranked below every event-specific signal (including the "(Online)" title
// inference): chrome describes the site, so on a multi-venue platform an
// office address in the footer must lose to any per-event location the page
// exposes — platforms publish JSON-LD/meta locations, which win far earlier.
function chromeAddress() {
  const markers = [
    (root) => [...root.querySelectorAll("a[href]")].filter((a) => MAPS_SERVICE.test(a.getAttribute("href"))),
    (root) => root.querySelectorAll('[class*="addres" i], [id*="addres" i]'),
    (root) =>
      [...root.querySelectorAll("a")].filter((a) =>
        [...a.querySelectorAll("img")].some((img) =>
          PIN_ICON.test(`${img.getAttribute("src") || ""} ${img.getAttribute("data-src") || ""}`)
        )
      ),
  ];
  for (const scope of ['footer, [class*="footer" i], [id*="footer" i]', 'header, [class*="header" i], [id*="header" i]']) {
    const roots = document.querySelectorAll(scope);
    for (const marked of markers) {
      for (const root of roots) {
        for (const el of marked(root)) {
          const address = addressText(el);
          if (address) return withSiteVenue(address);
        }
      }
    }
  }
  return "";
}

// The candidate's own visible text. In a real (scripting-enabled) Chrome a
// <noscript>'s content is one RAW TEXT node — naive textContent would splice
// image markup into the address (the gcec RULES.md jsdom-vs-Chrome trap
// that bit custom/telavivcinematheque.js) — so noscript/script/style subtrees
// are dropped from a clone before reading. A leading "Address:"-style label
// is dropped too.
function addressText(el) {
  const copy = el.cloneNode(true);
  for (const n of copy.querySelectorAll("noscript, script, style")) n.remove();
  const t = clean(copy.textContent).replace(/^(?:address|כתובת)\s*:\s*/i, "");
  return looksLikeAddress(t) ? t : "";
}

// Live extraction tests — the suite you review to confirm the extractor
// produces the right values for each supported site.
//
// These run OFFLINE against committed cached HTML files in
// data/, recorded from each site by the auto-extractor pipeline
// (the gcec create-extractor task, which fetches through ScraperAPI). Asserting against a cached copy of the real page
// makes the suite deterministic and runnable anywhere (no network), while still
// reflecting each site's current markup.
//
// Each JSON file in dev/requirements/extractor/expected/ describes one scenario. The
// extractor always returns a list of events; each event carries its timing in
// `times[]` (the multi-instance model — one entry per showing), so `expected`
// looks like:
//
//   {
//     "description": "Meetup event page is parseable",
//     "expected": {
//       "events": [
//         {
//           "title":      "Exact Title",
//           "ctz":        "America/New_York",   <- the Calendar URL's ctz= param, or null
//           "details":    "[https://...](https://.../)\n\n...full description...",
//           "times": [
//             {
//               "start":                "2026-06-25T18:00:00-04:00",
//               "end":                  "2026-06-25T21:00:00-04:00",
//               "eventLengthInMinutes": null,  <- explicit page duration, or null
//               "location":             "Brooklyn Public Library, 10 Grand Army Plaza, Brooklyn, NY"
//             }
//           ]
//         }
//       ]
//     }
//   }
//
// The scenario's source URL lives alongside the cached HTML, in
// data/<provenance>/<name>.url, where <provenance> is server-fetched/
// (pipeline-recorded) or user-submitted/ — the single source of truth —
// create-extractor's sweep records it, and the suite loads the HTML into a DOM at
// that URL so hostname-based site detection behaves as in Chrome). It is NOT
// repeated in the case file.
//
// `expected.events` must be the *complete*, exact array the extractor
// produces. Each event is deep-equal compared against:
//   { title, ctz, details, times: [{ start, end, eventLengthInMinutes, location }] }
// Location is per-showing (no top-level field): a single-venue event repeats it
// across its showings, a touring show varies it.
// There are no substring/regex/prefix matchers: every field must be present
// and match exactly, including the full text of `details`. `details` is the
// same for every instance (only the date differs between them), so it's
// asserted once at the event level. This catches any drift — in extraction or
// in how `details` is composed — however small, and the array lengths pin down
// how many events were found and how many instances each has (one event with
// one instance for an ordinary page; several events for a listing/series page;
// one event with several instances for a multi-screening/multi-night run). When
// a cache refresh legitimately changes a page, update `expected` to match.
//
// Per event: `details` is what events-popup/build-calendar-url.js's
// buildCalendarUrl() puts in the `details=` param (a link back to the source
// page followed by the description). `ctz` is the timezone a site extractor
// pinned the event to
// (e.g. "GB" for edfringe.com), or null.
//
// To cover a new website or platform: add a dev/requirements/extractor/data/server-fetched/<name>.url
// with the event page URL and a case file (dev/requirements/extractor/expected/<name>.json) with its
// `expected`. The cached HTML is recorded by the auto-extractor pipeline (open an
// `extractor-request` issue with the page URL and the create-extractor task does
// the rest); to add just a page, commit its .url and create-extractor's sweep
// fetches it. Run the suite once to see the actual extracted
// values in the failure output, then copy them into `expected`.
