1	// Date helpers: normalize raw datetime attributes / JSON-LD values, and scan
2	// free-form text for the first date (optionally with a time), all reduced to
3	// the extractor's start/end string contract:
4	//   "YYYY-MM-DD"                  -> all-day event
5	//   "YYYY-MM-DDTHH:MM[:SS]"       -> floating local time
6	//   full ISO with offset or "Z"   -> exact instant
7	//
8	// Uses GCal.clean (the dom helper) at call time. Augments globalThis.GCal
9	// (never replaces it) so load order can't clobber another file's contributions.
10	globalThis.GCal = Object.assign(globalThis.GCal || {}, (() => {
11	  const MONTH =
