13	  const TIME = "\\d{1,2}(?::\\d{2})?\\s*(?:a\\.?m\\.?|p\\.?m\\.?)|\\d{1,2}:\\d{2}";
14	  // Punctuation or connector words that can sit between a date and the time
15	  // after it, seen across sites: "June 14, 2026 at 7 PM", "16 June 2026 | 6:30 pm",
16	  // "14 Jun • 19:00", "Jun 14 2026 - 7 PM". One list so every date pattern below
17	  // (and the cleanup that hands the match to Date()) recognize the same set,
18	  // instead of each re-listing a slightly different subset.
19	  const SEP = "(?:,|\\||·|•|@|—|–|-|at|from)";
