25	  // Convert a Date plus a "did the source include a clock time" flag into the
26	  // string contract above. Floating local time is used so the calendar
27	  // template shows the same wall-clock time the page did.
28	  function dateToString(d, hasTime) {
29	    const day = `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
30	    return hasTime ? `${day}T${pad(d.getHours())}:${pad(d.getMinutes())}:00` : day;
31	  }
