1	// somo.social event pages: https://somo.social/en/e/anecdotes-presents-advanced-727
2	//
3	// The page is a React/Next.js app that server-renders one event, and publishes
4	// a complete schema.org Event JSON-LD block (name, startDate/endDate with UTC
5	// offsets, description as markdown, location as a Place). We take start/end
6	// straight from that embedded event (there is no <time datetime> node in the
7	// DOM), and override the fields the DOM states better than the JSON-LD:
8	//
9	//   title       the page's first <h1> (the event headline; later <h1>s belong
10	//               to the cookie-consent dialog)
11	//   location    the header venue line — an <a> linking to a Google Maps search
12	//               whose <span> holds the full address ("<venue>, <street>,
13	//               <city>, <country>"). The JSON-LD location.name is only the bare
14	//               venue name, with an empty PostalAddress, so the DOM span is the
15	//               fuller value.
16	//   description the "About the event" block (EventDescriptionClamp), rendered
17	//               with the block helpers so its bullet list and links survive as
18	//               text. The JSON-LD description carries the same copy but as raw
19	//               markdown (** and [text](url)), so the rendered DOM reads cleaner.
20	//   ctz         the venue's timezone — see ctzFromCountry below.
21	//
22	// TIMEZONE (ctz): somo hosts events worldwide, so the zone is per-event, not a
23	// fixed site constant. The page is no help by the usual routes: its schema.org
24	// PostalAddress is empty (no addressCountry), and the only IANA zone it embeds
25	// in inline JSON is "Europe/Stockholm" — the site's own rendering zone (it shows
26	// this event as "5:00 PM", i.e. 15:00 UTC in Stockholm), NOT the venue's — while
27	// the startDate/endDate are serialized in UTC (+00:00), so their offset doesn't
28	// reflect the venue either. The one venue-country signal the page gives is the
29	// country at the end of the address line, so we derive ctz from that. ctz only
30	// changes the Calendar event's displayed zone (the instant is fixed by the
31	// +00:00 start/end), so anchoring a Tel Aviv event to Asia/Jerusalem shows it at
32	// the correct local 18:00 rather than the viewer's zone.
33	//
34	// start/end come from the generic base's read of that embedded event; the four
35	// fields above are the overrides this source states.
36	(() => {
37	  const { text, blockText } = GCal;
38	
39	  // Map the address's trailing country name to its IANA zone, reusing the
40	  // canon's country→zone table (COUNTRY_TIMEZONES, keyed by ISO region code)
41	  // with the codes inverted to English names via Intl. Only single-zone
42	  // countries yield a zone: a country alone can't pick between a multi-zone
43	  // country's regions, and an unrecognized name gives nothing — so we never
44	  // emit a wrong ctz, only a right one or none (the derive-timezone contract).
45	  function ctzFromCountry(location) {
46	    const country = (location.split(",").pop() || "").trim().toLowerCase();
47	    if (!country) return "";
48	    let names;
49	    try {
50	      names = new Intl.DisplayNames(["en"], { type: "region" });
51	    } catch (e) {
52	      return "";
53	    }
54	    for (const [code, zones] of Object.entries(GCal.COUNTRY_TIMEZONES || {})) {
55	      if (zones.length !== 1) continue;
56	      let name;
57	      try {
58	        name = names.of(code);
59	      } catch (e) {
60	        continue;
61	      }
