"use strict";
const fs = require("node:fs");
const path = require("node:path");
const { pathToFileURL } = require("node:url");
const { extractFromHtml } = require("./harness");

async function main() {
  const { buildCalendarUrl } = await import(
    pathToFileURL(path.join(__dirname, "..", "extension", "events-popup", "build-calendar-url.js"))
  );

  const html = fs.readFileSync(
    path.join(__dirname, "..", "dev/requirements/extractor/data/server-fetched/tzavta.html"),
    "utf8"
  );
  const url = fs
    .readFileSync(path.join(__dirname, "..", "dev/requirements/extractor/data/server-fetched/tzavta.url"), "utf8")
    .trim();

  const extracted = extractFromHtml(html, url);
  const events = [...(extracted.events || [])].map((e) => {
    const tab = { url, title: e.title, index: 0 };
    const calendarUrl = buildCalendarUrl(e, tab, 0);
    return {
      title: e.title,
      ctz: e.ctz || null,
      details: new URL(calendarUrl).searchParams.get("details"),
      times: [...e.times].map((t) => ({
        start: t.start,
        end: t.end || null,
        eventLengthInMinutes: t.eventLengthInMinutes ?? null,
        location: t.location || null,
      })),
    };
  });

  console.log(JSON.stringify({ description: "REPLACE_ME", expected: { events } }, null, 2));
}

main();

